  function dramaticRoll(opts){
    const diceSides=Math.max(2,Math.floor(Number(opts?.diceSides)||6)),rollSet=count=>diceSides===6?v314RollDice(count):Array.from({length:count},()=>secureDieSides(diceSides)),face=value=>diceSides===6?FACES[Math.max(1,Math.min(6,Number(value)||1))-1]:String(value);
    if(appState.hideDiceRolls){
      const rolls=rollSet(Math.max(1,Number(opts?.diceCount)||2)),outcome=opts?.evaluate?opts.evaluate(rolls):{total:rolls.reduce((a,b)=>a+b,0),headline:'RESULTADO',detail:''},total=outcome?.total??rolls.reduce((a,b)=>a+b,0);
      try{opts?.onOutcome?.(outcome,rolls);}catch(err){console.warn('Falha em efeito de rolagem',err);}
      return Promise.resolve({rolls,total,outcome});
    }
    /* v299: uma rolagem é uma sessão única. Nunca reutilize callbacks de um dialog anterior. */
    cancelActiveDiceRoll('superseded');
    return new Promise(resolve=>{
      const overlay=el('diceOverlay'),row=el('diceRow'),rollBtn=el('diceRollBtn'),contBtn=el('diceContinueBtn'),close=el('diceClose');
      let rolling=false,finished=false,timer=null,settled=false,resultValue=null;
      if(!overlay||!row||!rollBtn||!contBtn||!close){console.error('Superfície de dados incompleta.',{overlay:!!overlay,row:!!row,rollBtn:!!rollBtn,contBtn:!!contBtn,close:!!close});resolve(null);return;}
      const serial=++diceSessionSerial;
      const isCurrent=()=>activeDiceSession?.serial===serial;
      const detach=()=>{rollBtn.onclick=null;contBtn.onclick=null;close.onclick=null;overlay.oncancel=null;/* não usar onclose: um evento close atrasado de uma sessão antiga poderia cancelar a nova */};
      const closeSurface=()=>{if(timer){clearInterval(timer);timer=null;}detach();overlay.classList.add('hidden');try{if(overlay.open&&typeof overlay.close==='function')overlay.close();else overlay.removeAttribute('open');}catch{overlay.removeAttribute('open');}};
      const settle=value=>{if(settled)return;settled=true;resultValue=value;if(isCurrent())activeDiceSession=null;closeSurface();resolve(value);};
      const cancelRoll=()=>{if(settled)return;settle(null);};
      const session={serial,overlay,cancel:()=>cancelRoll()};activeDiceSession=session;

      /* neutraliza restos visuais sem instalar um callback de close que possa atingir a nova sessão */
      detach();
      try{if(overlay.open&&typeof overlay.close==='function')overlay.close();else overlay.removeAttribute('open');}catch{overlay.removeAttribute('open');}
      overlay.classList.add('hidden');
      el('diceTitle').textContent=opts.title||'Rolar dados';el('diceLead').textContent=opts.lead||'';renderDiceCombatDuel(opts.combatDuel||null);el('diceEquation').textContent='';el('diceConsequence').textContent='';el('diceConsequence').classList.remove('show');el('diceDetail').textContent='';el('diceDetail').classList.remove('show');row.innerHTML='';rollBtn.classList.remove('hidden');rollBtn.disabled=false;contBtn.classList.remove('show');close.disabled=false;
      const dice=createAnimatedDice(row,opts.diceCount||2,{sides:diceSides});overlay.classList.remove('hidden');
      if(typeof overlay.showModal==='function'){try{overlay.showModal();}catch(e){try{overlay.setAttribute('open','');}catch{cancelRoll();return;}}}else overlay.setAttribute('open','');
      overlay.oncancel=e=>{e.preventDefault();if(!rolling&&!finished)cancelRoll();};
      close.onclick=()=>{if(!rolling&&!finished)cancelRoll();};
      rollBtn.onclick=()=>{
        if(rolling||settled||!isCurrent())return;rolling=true;close.disabled=true;rollBtn.disabled=true;rollBtn.classList.add('hidden');dice.forEach(d=>d.classList.add('rolling'));if(navigator.vibrate)navigator.vibrate(35);primeAudio();let tick=0;timer=setInterval(()=>{if(!isCurrent()){clearInterval(timer);timer=null;return;}tick++;dice.forEach((d,i)=>d.textContent=diceSides===6?FACES[(tick+i*2)%6]:String(1+((tick+i*3)%diceSides)));boneClick(.032+(tick%3)*.006);},72);
        setTimeout(()=>{if(settled||!isCurrent())return;if(timer){clearInterval(timer);timer=null;}const rolls=rollSet(dice.length);dice.forEach((d,i)=>{d.classList.remove('rolling');d.textContent=face(rolls[i]);});boneClick(.065);const outcome=opts.evaluate?opts.evaluate(rolls):{total:rolls.reduce((a,b)=>a+b,0),headline:'RESULTADO',detail:''};try{opts?.onOutcome?.(outcome,rolls);}catch(err){console.warn('Falha em efeito de rolagem',err);}if(opts.combatDuel)renderDiceCombatDuel(opts.combatDuel);const total=outcome.total??rolls.reduce((a,b)=>a+b,0);resultValue={rolls,total,outcome};el('diceEquation').textContent=outcome.equation||`${rolls.join(' + ')} = ${total}`;setTimeout(()=>{if(!settled&&isCurrent()){el('diceConsequence').textContent=outcome.headline||'';el('diceConsequence').classList.add('show');}},520);setTimeout(()=>{if(settled||!isCurrent())return;renderDiceOutcomeDetail(outcome);el('diceDetail').classList.add('show');contBtn.classList.add('show');finished=true;rolling=false;contBtn.onclick=()=>settle(resultValue);},820);},1450);
      };
      if(opts.autoRoll)setTimeout(()=>{if(!rolling&&!finished&&!settled&&isCurrent()&&!overlay.classList.contains('hidden'))rollBtn.onclick?.();},90);
    });
  }

  function replacePlayerCurrency(player,count){if(!player)return 0;const qty=Math.max(0,Math.round(Number(count)||0));if(!Array.isArray(player.items))player.items=[];player.items=player.items.filter(item=>!isGoldItem(item));for(let i=0;i<qty;i++)player.items.push('Ouro');player.initialCurrency=qty;return qty;}
