  function normalizeCustomRecipe(recipe={}){return {a:itemMeta(recipe.a||'').raw||String(recipe.a||'').trim(),b:itemMeta(recipe.b||'').raw||String(recipe.b||'').trim(),result:itemMeta(recipe.result||'').raw||String(recipe.result||'').trim(),hours:Math.max(.5,Number(recipe.hours)||1)};}
