  function craftIngredientAvailable(name,firstName=''){const need=craftName(name),first=craftName(firstName);if(need==='provisao')return (appState.player?.provisions||0)>0;if(need===first){const entry=inventoryCounts().find(e=>craftName(e.meta.raw)===need);return (entry?.count||0)>=2;}return inventoryCounts().some(e=>craftName(e.meta.raw)===need);}
