  function craftingAllowed(){return !!appState.player&&!appState.editor&&!adventureEnded()&&!combatInProgress()&&!ensureSanityRuntime().activeEpisode;}
  function craftAvailableRecipesForIngredient(value){if(!craftingAllowed())return [];const name=craftName(value);return craftRecipesForIngredient(value).filter(r=>{const other=craftName(r.a)===name?r.b:r.a;return craftIngredientAvailable(other,value);});}
