  function craftHoursLabel(hours){const n=Number(hours)||.5;return `${String(n).replace('.',',')} ${n===1?'hora':'horas'}`;}
  function cancelCrafting({render=true}={}){appState.craftingIngredientKey=null;appState.craftingBusy=false;if(render&&inventoryOpen())renderInventory();}
  function startCrafting(key){if(!craftingAllowed())return;const entry=inventoryEntry(key);if(!entry||!craftAvailableRecipesForIngredient(entry.meta.raw).length)return;appState.craftingIngredientKey=key;appState.inventorySelection=key;renderInventory();}
