  function promptCraftCombination(secondRaw){const first=craftFirstEntry();if(!first)return;const recipe=craftRecipeFor(first.meta.raw,secondRaw);if(!recipe)return;const firstName=first.meta.name,secondName=isProvisionName(secondRaw)?'Provisão':itemMeta(secondRaw).name,result=itemMeta(recipe.result).name;confirmSpecial('Produzir item',`${firstName} + ${secondName} serão consumidos para produzir ${result}. Tempo necessário: ${craftHoursLabel(recipe.hours)}. Deseja produzir?`,()=>completeCraft(recipe,first.meta.raw,secondRaw),'Produzir');}
  function selectCraftProvision(){const first=craftFirstEntry();if(!first||!(appState.player?.provisions>0))return;const recipe=craftRecipeFor(first.meta.raw,'Provisão');if(recipe)promptCraftCombination('Provisão');}
  function hasRequirementItem(item){if(hasItem(item))return true;return craftName(item)==='corda'&&hasItem('Gancho de Escalada');}
  function activeEntriesByCategory(category){const want=categoryKey(category),active=ensureActiveItems();return inventoryCounts().filter(e=>categoryKey(e.meta.category)===want&&active[e.meta.key]);}
