  function activeReadyEntries(){const byKey=new Map(inventoryCounts().map(e=>[e.meta.key,e])),active=ensureActiveItems();return ensureActiveOrder().map(key=>byKey.get(key)).filter(e=>e&&active[e.meta.key]);}
