  function armorProfile(metaOrName){const name=(typeof metaOrName==='string'?itemMeta(metaOrName).name:metaOrName?.name||'').toLocaleLowerCase('pt-BR');return ARMOR_PROFILES[name]||{guard:1,penalty:0};}
  function armorGuard(){const a=activeArmor();if(!a)return 0;const p=appState.player;if(!p)return 0;const max=armorProfile(a.meta).guard;if(!p.armorGuard||p.armorGuard<1)p.armorGuard=max;return Math.max(0,Math.min(max,p.armorGuard));}
