  function breakActiveArmor(entry){if(!entry)return;const meta=entry.meta;removeOneItem(meta.raw,{journal:false});recordJournal(`${meta.name} se quebrou.`,{kind:'item'});delete ensureActiveItems()[meta.key];if(appState.player)appState.player.armorGuard=0;toast(`${meta.name} se quebrou.`);}
