  const SELF_MAGIC_NAMES=new Set(['cura','benção','maestria','abrir caminho','voltar no tempo','invisibilidade','aura','buraco mágico','premonição','mãos múltiplas','soltar-se','contra-feitiço']);
  const MAGIC_COSTS={'benção':1,'bola de fogo':2,'cura':2,'maestria':2,'fraqueza':2,'medo':2,'fortaleza':2,'voar':2,'soltar-se':2,'abrir caminho':3,'invisibilidade':3,'ilusão':3,'sono':3,'aura':3,'premonição':3,'mãos múltiplas':4,'cura total':4,'buraco mágico':4,'voltar no tempo':4,'conjurar goblin':3,'reflexo aéreo':3,'camuflagem mística':3,'desconcertar':3,'grande benção':3,'telecinese':3,'aceleração':4,'pele fluida':3,'armadura de espinhos':3,'dreno de vida':4,'veneno mágico':3,'contra-feitiço':4};
  function magicCost(spellOrMeta){const name=(typeof spellOrMeta==='string'?spellOrMeta:spellOrMeta?.name||'').toLocaleLowerCase('pt-BR').trim();return MAGIC_COSTS[name]||2;}
  function ensureTemporarySpells(){const p=appState.player;if(!p)return [];if(!Array.isArray(p.temporarySpells))p.temporarySpells=[];return p.temporarySpells;}
  function temporarySpellTurns(key){const matches=ensureTemporarySpells().filter(x=>x.key===key);return matches.length?Math.max(...matches.map(x=>Math.max(0,Number(x.remaining)||0))):0;}
  function consumeTemporarySpellTracking(key){const list=ensureTemporarySpells(),i=list.findIndex(x=>x.key===key);if(i>=0){list.splice(i,1);return true;}return false;}
  function removeLastItemByKey(key){const items=appState.player?.items||[];let i=-1;for(let n=items.length-1;n>=0;n--)if(itemMeta(items[n]).key===key){i=n;break;}if(i<0)return false;const meta=itemMeta(items[i]);items.splice(i,1);if(!items.some(x=>itemMeta(x).key===key)){delete ensureActiveItems()[key];if(appState.inventorySelection===key)appState.inventorySelection=null;}return true;}
  function consumeSpellItem(meta){if(!meta)return false;const temporary=consumeTemporarySpellTracking(meta.key);return temporary?removeLastItemByKey(meta.key):removeOneItem(meta.raw,{journal:false});}
  async function temporarySpellDuration(){if(knowledgeValue('Treino Mágico')<=0)return 3;const roll=await dramaticRoll({title:'Duração do Feitiço',lead:'Seu Treino Mágico prolonga o Feitiço. Role 1d6: ele ficará disponível por 1d6 + 3 turnos.',diceCount:1,evaluate:r=>({total:r[0]+3,equation:`${r[0]} + 3 = ${r[0]+3}`,headline:`${r[0]+3} TURNOS`,detail:'Até o fim desse prazo, o Feitiço pode ser lançado normalmente.',turns:r[0]+3})});return roll?.outcome?.turns||6;}
  async function grantTemporarySpell(raw){const meta=itemMeta(raw);if(categoryKey(meta.category)!=='feitiço')return false;const turns=await temporarySpellDuration();addQuantity(meta.raw,1,{force:true,silent:true});ensureTemporarySpells().push({key:meta.key,raw:meta.raw,remaining:turns});activateItemMeta(meta);await showRewardMoment({kind:'magic',title:'FEITIÇO ENGARRAFADO',headline:meta.name.toUpperCase(),detail:`O Feitiço fica disponível por ${turns} turno${turns===1?'':'s'} e desaparece se permanecer sem uso.`,icon:'🧪'});return true;}
  function tickTemporarySpells(){const list=ensureTemporarySpells();if(!list.length)return;const keep=[];for(const fx of list){fx.remaining=Math.max(0,(Number(fx.remaining)||1)-1);if(fx.remaining<=0){removeLastItemByKey(fx.key);toast(`${itemMeta(fx.raw).name} desapareceu antes de ser lançado.`);}else keep.push(fx);}appState.player.temporarySpells=keep;}
  function tickMultiHands(){const p=appState.player;if(!p||(Number(p.multiHandsTurns)||0)<=0)return;p.multiHandsTurns=Math.max(0,(Number(p.multiHandsTurns)||0)-1);if(p.multiHandsTurns===0){for(const rec of ensureLingeringSpells())if(lingeringMagicName(rec.name||itemMeta(rec.raw).name)==='mãos múltiplas')deactivateActiveKey(rec.key);normalizeActiveLoadout();toast('Mãos Múltiplas terminou. Seu limite voltou a 2 itens ativos.');}}
  const LINGERING_MAGIC_NAMES=new Set(['maestria','fraqueza','ilusão','sono','aura','mãos múltiplas']);
  function lingeringMagicName(metaOrName){return (typeof metaOrName==='string'?metaOrName:metaOrName?.name||'').toLocaleLowerCase('pt-BR').trim();}
  function isLingeringMagic(metaOrName){const name=lingeringMagicName(metaOrName);return LINGERING_MAGIC_NAMES.has(name)||/^conjurar\s+/.test(name);}
  function ensureLingeringSpells(){const p=appState.player;if(!p)return [];if(!Array.isArray(p.lingeringSpells))p.lingeringSpells=[];return p.lingeringSpells;}
  function lingeringSpellRecord(key){return ensureLingeringSpells().find(x=>x.key===key)||null;}
  function lingeringSpellEffectActive(rec){
    if(!rec||!appState.player)return false;const name=lingeringMagicName(rec.name||itemMeta(rec.raw).name),p=appState.player,c=appState.combat;
    if(name==='aura')return (Number(p.auraTurns)||0)>0;
    if(name==='mãos múltiplas')return (Number(p.multiHandsTurns)||0)>0;
    if(name==='maestria')return (p.skillModifiers||[]).some(m=>m.source==='maestria'&&(Number(m.remaining)||0)>0);
    if(name==='fraqueza')return !!(c&&!c.won&&(Number(c.weaknessTurns)||0)>0);
    if(name==='ilusão')return !!(c&&!c.won&&(Number(c.illusionTurns)||0)>0);
    if(name==='sono')return !!(c&&!c.won&&(Number(c.sleepTurns)||0)>0);
    if(/^conjurar\s+/.test(name)){
      if(!c||c.won)return false;const spec=parseSummonSpell(itemMeta(rec.raw)),summonName=(spec?.name||name.replace(/^conjurar\s+/,'')).toLocaleLowerCase('pt-BR');
      if(combatSummons(c).some(x=>String(x.name||'').toLocaleLowerCase('pt-BR')===summonName))return true;
      const mainRemaining=Math.max(0,(Number(c.summonedMainExpiresAtRound)||0)-(Number(c.round)||0));return !!(c.summonedMain&&mainRemaining>0&&String(c.name||'').toLocaleLowerCase('pt-BR')===summonName);
    }
    return false;
  }
  function registerLingeringSpell(meta){if(!meta||!isLingeringMagic(meta))return false;const list=ensureLingeringSpells();if(list.some(x=>x.key===meta.key))return true;const temporary=consumeTemporarySpellTracking(meta.key);list.push({key:meta.key,raw:meta.raw,name:meta.name,temporary});ensureActiveItems()[meta.key]=true;return true;}
  function finishLingeringSpell(rec){if(!rec)return false;const meta=itemMeta(rec.raw),removed=rec.temporary?removeLastItemByKey(rec.key):removeOneItem(rec.raw);delete ensureActiveItems()[rec.key];if(appState.inventorySelection===rec.key&&!inventoryEntry(rec.key))appState.inventorySelection=null;return removed||!inventoryEntry(rec.key);}
  function cleanupExpiredLingeringSpells(){const p=appState.player,list=ensureLingeringSpells();if(!p||!list.length)return;const keep=[];for(const rec of list){if(lingeringSpellEffectActive(rec)){keep.push(rec);continue;}const name=rec.name||itemMeta(rec.raw).name;finishLingeringSpell(rec);recordJournal(`O efeito de ${name} terminou.`,{kind:'magic',dedupeKey:`spell-end:${rec.key}`});toast(`${name} terminou e desapareceu do Equipamento.`);}p.lingeringSpells=keep;}
  function potionSpellGrant(effect=''){const t=String(effect||'').trim(),m=t.match(/^\{\+\s*(.+\(Feitiço\)(?:\|[^{}]+)?)\}$/i);return m?itemMeta(m[1]).raw:'';}
  async function usePotion(meta){if(!meta||categoryKey(meta.category)!=='poções')return false;const effect=String(meta.itemEffect||'').trim();if(!effect){if(/^poção da cura$/i.test(meta.name)){useCurePotion();return true;}if(/^poção maravilhosa$/i.test(meta.name)){usePowerPotion();return true;}removeOneItem(meta.raw,{journal:false});journalRecordUse(meta.raw);scheduleCustomItemDelayedEffects(meta);toast(`${meta.name} foi consumida.`);renderAll();return true;}removeOneItem(meta.raw,{journal:false});journalRecordUse(meta.raw);scheduleCustomItemDelayedEffects(meta);const spellRaw=potionSpellGrant(effect);if(spellRaw)await grantTemporarySpell(spellRaw);else if(!(await applySimpleMarkerEffect(effect,{source:'POÇÃO'})))toast(`Efeito de ${meta.name} ainda sem executor.`);if(inventoryOpen())renderInventory();renderAll();return true;}
