  function ensureChalkNotes(){const p=appState.player;if(!p)return {};if(!p.chalkNotes||typeof p.chalkNotes!=='object')p.chalkNotes={};return p.chalkNotes;}
  function renderChalkNote(storyBox){if(!storyBox||appState.editor)return;const notes=ensureChalkNotes(),id=appState.sectionId,note=String(notes[id]||''),canWrite=hasActiveNamedItem('Giz');if(!note&&!canWrite)return;const box=document.createElement('div');box.className='chalk-note-box';if(note){const row=document.createElement('div');row.className='chalk-note-saved';const copy=document.createElement('div');copy.innerHTML=`<strong>Você escreveu:</strong> ${esc(note)}`;const del=document.createElement('button');del.type='button';del.className='chalk-note-delete';del.textContent='✕';del.title='Apagar anotação';del.setAttribute('aria-label','Apagar anotação');del.onclick=()=>{delete notes[id];renderAll();};row.append(copy,del);box.appendChild(row);}else{const input=document.createElement('input');input.type='text';input.className='chalk-note-input';input.placeholder='Escreva com o Giz e pressione Enter';input.setAttribute('aria-label','Escrever com o Giz nesta seção');input.addEventListener('keydown',e=>{if(e.key!=='Enter')return;e.preventDefault();const text=input.value.trim();if(!text)return;notes[id]=text;addState('Marcou o Caminho');renderAll();});box.appendChild(input);}storyBox.appendChild(box);}
  async function activateTorch(meta){const p=ensureTimeState();if(!p)return false;if(Number(p.torchTurns)>0)return true;const roll=await dramaticRoll({title:'Acender Tocha',lead:'Role 2d6. A Tocha iluminará áreas ou horas escuras por esse número de turnos.',diceCount:2,evaluate:r=>{const total=r[0]+r[1];return {total,equation:`${r[0]} + ${r[1]} = ${total}`,headline:`LUZ POR ${total} TURNOS`,detail:'Enquanto estiver em prontidão, a Tocha vence a escuridão.',turns:total};}});if(!roll)return false;p.torchTurns=roll.outcome.turns;return true;}
