  function pleasureRecoveryInfo(meta){if(categoryKey(meta?.category)!=='prazer')return null;let sanityGain=0,lifeCost=0;for(const token of pleasureEffectTokens(meta)){const m=token.match(/^\{([+-])\s*(\d+)\s+(APTIDÃO|APTIDAO|VIDA|SANIDADE|FORTUNA)\}$/i);if(!m)continue;const stat=normalizeStatToken(m[3]),amount=(m[1]==='+'?1:-1)*(parseInt(m[2],10)||0);if(stat==='SANIDADE'&&amount>0)sanityGain+=amount;if(stat==='VIDA'&&amount<0)lifeCost+=-amount;}return {sanityGain,lifeCost};}
